# Example to check file encoding
def check_file_encoding(file_content):
    try:
        file_content.decode('utf-8')
        return True
    except UnicodeDecodeError:
        return False

# Test the function
print(check_file_encoding(b'Hello World'))  # Should return True
print(check_file_encoding(b'\x80\x81\x82'))  # Should return False
